func genDataSourcesWriteDeleteCmd() *cobra.Command {
	var dataJSON string
	var fID int64
	cmd := &cobra.Command{
		Use:   "datasource-delete",
		Short: "Delete datasource",
		Long: `Delete datasource.

Delete a datasource by ID; alert rules that reference it are not blocked.

API: POST /monit/datasource/delete (monit-datasource-write-delete)

Request fields:
  --id int (required) — Numeric ID of the target resource; the exact meaning depends on the API being called (e.g. datasource ID, ruleset ID).
`,
		Example: `  flashduty monit datasource-delete --data '{"id":10}'`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runCommand(cmd, args, func(ctx *RunContext) error {
				body, err := genAssembleBody(dataJSON, func(body map[string]any) error {
					if cmd.Flags().Changed("id") {
						body["id"] = fID
					}
					return nil
				})
				if err != nil {
					return err
				}
				req := new(flashduty.IDRequest)
				if err := genBindBody(ctx.Cmd.ErrOrStderr(), body, req); err != nil {
					return err
				}
				resp, err := ctx.Client.DataSources.WriteDelete(cmdContext(ctx.Cmd), req)
				if err != nil {
					return err
				}
				return printRawOrNoPayload(ctx, resp)
			})
		},
	}
	cmd.Flags().Int64Var(&fID, "id", 0, "Numeric ID of the target resource; the exact meaning depends on the API being called (e.g. datasource ID, ruleset ID). (required)")
	cmd.Flags().StringVar(&dataJSON, "data", "", "Full request body as JSON; positional arguments and typed flags override its fields. Accepts inline JSON, or - to read stdin.")
	return cmd
}

